<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { errorMessage } from '@/lib/api'
import { useBookingStore } from '@/stores/booking'
import { useAuthStore } from '@/stores/auth'

const store = useBookingStore(); const auth = useAuthStore(); const router = useRouter(); const date = ref(new Date().toISOString().slice(0, 10)); const selected = ref<number | null>(null); const timeFilter = ref('all'); const loading = ref(false); const error = ref('')
const total = computed(() => store.selectedSlots.reduce((sum, slot) => sum + slot.price, 0)); const money = (value: number) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(value); const image = (index: number) => store.courts[index]?.image_url || `/aura/court-${index + 4}.jpg`
const visibleSlots = computed(() => store.slots.filter((slot) => { const hour = Number(new Date(slot.startsAt).toLocaleTimeString('en-US', { timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', hour12: false })); return timeFilter.value === 'morning' ? hour < 17 : timeFilter.value === 'evening' ? hour >= 17 : true }))

async function loadAvailability() { if (selected.value) { try { await store.loadAvailability(selected.value, date.value) } catch { /* store exposes the user-facing error */ } } }
async function chooseCourt() { await loadAvailability() }
async function submit() { if (!auth.user) return router.push({ name: 'login', query: { redirect: '/booking' } }); if (!store.selectedSlots.length) return; loading.value = true; error.value = ''; try { const result = await store.createBooking(); router.push('/payment/' + result.booking.code) } catch (cause: unknown) { error.value = errorMessage(cause, 'Không thể tạo lịch đặt sân.') } finally { loading.value = false } }
function scrollToAvailability() { document.getElementById('availability')?.scrollIntoView({ behavior: 'smooth' }) }

onMounted(async () => { try { await store.loadCourts(); selected.value = store.courts[0]?.id || null; await loadAvailability() } catch { /* store exposes the user-facing error */ } })
</script>

<template>
  <section class="hero"><div><div class="eyebrow">Thể thao chuyên nghiệp</div><h1>Nơi chính xác <em>tạo nên phong độ.</em></h1><p>Trải nghiệm nhịp điệu của trận đấu trên những sân cầu lông chuyên nghiệp. Đặt sân trong vài giây và bắt đầu cuộc chơi.</p><div class="actions"><RouterLink to="/courts" class="btn">Đặt sân <span class="material-symbols-outlined">arrow_forward</span></RouterLink><a href="#features" class="btn secondary">Khám phá Aura</a></div></div><div class="hero-mosaic"><div><img class="short" src="/aura/court-1.jpg" alt="Sân cầu lông Aura Court" /><img class="tall" src="/aura/court-2.jpg" alt="Sàn sân cầu lông" style="margin-top:12px" /></div><div><img class="tall" src="/aura/court-3.jpg" alt="Vận động viên cầu lông" /><div class="access-card" style="margin-top:12px"><div><strong>24/7</strong><span>MỞ CỬA</span></div></div></div></div></section>
  <section class="search-strip"><div class="search-field"><label>Sân</label><select v-model.number="selected" @change="chooseCourt"><option v-for="court in store.courts" :key="court.id" :value="court.id">{{ court.name }}</option></select></div><div class="search-field"><label>Ngày</label><input v-model="date" type="date" @change="loadAvailability" /></div><div class="search-field"><label>Khung giờ</label><select v-model="timeFilter"><option value="all">Tất cả khung giờ</option><option value="morning">Buổi sáng · 06:00–17:00</option><option value="evening">Buổi tối · 17:00–23:00</option></select></div><button class="search-action" aria-label="Tìm khung giờ" @click="scrollToAvailability">search</button></section>
  <section class="section" id="availability"><div class="section-head"><div><div class="eyebrow">Khám phá sân</div><h2>Khung giờ còn trống</h2></div><RouterLink to="/courts" class="muted">Xem tất cả sân <span class="material-symbols-outlined">arrow_forward</span></RouterLink></div><p v-if="store.error" class="error">{{ store.error }}</p><div v-if="visibleSlots.length" class="slot-preview"><button v-for="slot in visibleSlots" :key="slot.startsAt" class="slot" :class="{ selected: store.selectedSlots.some((item) => item.startsAt === slot.startsAt), unavailable: !slot.available }" :disabled="!slot.available" @click="store.toggle(slot)">{{ new Date(slot.startsAt).toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' }) }}<small>{{ money(slot.price) }}</small></button></div><div class="court-grid"><RouterLink v-for="(court, index) in store.courts" :key="court.id" :to="`/courts/${court.id}`" class="court-card"><div class="court-card-image"><img :src="image(index)" :alt="court.name" /><span class="tag">Từ {{ money((court.price_slots?.[0]?.price || 120000)) }}/giờ</span></div><div class="court-info"><h3>{{ court.name }}</h3><p class="muted"><span class="material-symbols-outlined">location_on</span> {{ court.description || 'Câu lạc bộ Aura Court' }}</p></div></RouterLink></div></section>
  <section class="section" style="padding-top:10px" id="features"><div class="section-head"><div><div class="eyebrow">Tiêu chuẩn Aura</div><h2>Mọi thứ thật trọn vẹn.</h2></div></div><div class="feature-row"><article class="feature"><span class="feature-icon">bolt</span><h3>Đặt sân trong vài giây</h3><p class="muted">Lịch sân rõ ràng, chọn khung giờ nhanh và giữ chỗ tức thì.</p></article><article class="feature"><span class="feature-icon">verified</span><h3>Sân cao cấp</h3><p class="muted">Mặt sân, ánh sáng và không gian được chăm chút.</p></article><article class="feature"><span class="feature-icon">payments</span><h3>Thanh toán an toàn</h3><p class="muted">Thanh toán QR an toàn, trạng thái cập nhật theo thời gian thực.</p></article></div></section>
  <div v-if="store.selectedSlots.length" class="floating-booking"><span>{{ store.selectedSlots.length }} khung giờ · {{ money(total) }}</span><button class="btn pink" :disabled="loading" @click="submit">Tiếp tục</button></div><p v-if="error" class="error container">{{ error }}</p>
</template>
